{"data":{"startAt":0,"maxResults":100,"total":15,"isLast":true,"appliedContentFormat":"html","comments":[{"id":"3370838","author":{"accountId":"qm:77071153-8149-425d-9cc5-2ef53c35a3bd:8855bdee-baa1-46a5-962b-a2a977a9a4ef","displayName":"Erik Figueroa"},"body":"<div data-type="media-group"><div data-type="media" data-media-type="file" data-id="ea28edcd-2b2d-43fc-bb4b-ba176c46a819"></div></div><div data-type="media-group"><div data-type="media" data-media-type="file" data-id="9f56cbe3-cce2-4fc4-97ea-d3657a2279b8"></div></div>","created":"2026-09-28T17:11:53.344-0400","updated":"2026-09-28T17:11:53.344-0400","updateAuthor":{"accountId":"qm:77071153-8149-425d-9cc5-2ef53c35a3bd:8855bdee-baa1-46a5-962b-a2a977a9a4ef","displayName":"Erik Figueroa"},"jsdPublic":true},{"id":"3370840","author":{"accountId":"712020:b4c0c643-7648-43fd-ad84-b65f21a4e107","displayName":"Vismaya Thottada"},"body":"<p data-local-id="b074cf1d2728">Hello <span data-local-id="15163242-f08a-4238-8d89-d186542d836b" data-type="mention" data-user-id="qm:77071153-8149-425d-9cc5-2ef53c35a3bd:8855bdee-baa1-46a5-962b-a2a977a9a4ef">@Erik Figueroa</span> ,</p><p data-local-id="5f60b4c4886b">Thank you for contacting Appriss Retail Support.</p><p data-local-id="3739d37cd272">We’ve received your ticket and are routing it to the appropriate team for assistance. The assigned representative will follow up as soon as they’ve had a chance to review.</p><p data-local-id="e9b8060613b1">Kind Regards,</p><p data-local-id="1ac24cf1fb47">Appriss Retail Support </p>","created":"2026-09-28T17:14:13.131-0400","updated":"2026-09-28T17:14:13.131-0400","updateAuthor":{"accountId":"712020:b4c0c643-7648-43fd-ad84-b65f21a4e107","displayName":"Vismaya Thottada"},"jsdPublic":true},{"id":"3371058","author":{"accountId":"712020:036f5eba-7ec8-462c-b21b-264f8e744092","displayName":"Bikash Kumar"},"body":"<p data-local-id="36f5335f51a9">Hello Erik,</p><p data-local-id="f90a7e309fc4">I have taken ownership of this ticket and will be investigating it for you. Please allow some time for me to research the issue and I will get back with you just as soon as I have any information.</p><p data-local-id="b453ded9eeaf"></p><p data-local-id="180c3ae9da95">Thanks &amp; Regards,</p><p data-local-id="c10f8d172158">Appriss Retail Support</p>","created":"2026-09-29T01:40:12.619-0400","updated":"2026-09-29T01:40:12.619-0400","updateAuthor":{"accountId":"712020:036f5eba-7ec8-462c-b21b-264f8e744092","displayName":"Bikash Kumar"},"jsdPublic":true},{"id":"3373008","author":{"accountId":"qm:77071153-8149-425d-9cc5-2ef53c35a3bd:b7849520-7ee8-41e7-a23f-095dcda5a57a","displayName":"Manish Sethia"},"body":"<p>Please consider this immediate need</p>","created":"2026-09-30T13:02:14.720-0400","updated":"2026-09-30T13:02:14.720-0400","updateAuthor":{"accountId":"qm:77071153-8149-425d-9cc5-2ef53c35a3bd:b7849520-7ee8-41e7-a23f-095dcda5a57a","displayName":"Manish Sethia"},"jsdPublic":true},{"id":"3373013","author":{"accountId":"712020:b4c0c643-7648-43fd-ad84-b65f21a4e107","displayName":"Vismaya Thottada"},"body":"<p data-local-id="999cdd665509">Hi <span data-local-id="3eb52994-dce0-4c35-8bd1-7d19e6ccc044" data-type="mention" data-user-id="qm:77071153-8149-425d-9cc5-2ef53c35a3bd:b7849520-7ee8-41e7-a23f-095dcda5a57a">@Manish Sethia</span> ,<br>Your escalation has been received and will be updated once it has been reviewed.<br>Regards,  <br>Appriss Support </p>","created":"2026-09-30T13:04:31.200-0400","updated":"2026-09-30T13:04:31.200-0400","updateAuthor":{"accountId":"712020:b4c0c643-7648-43fd-ad84-b65f21a4e107","displayName":"Vismaya Thottada"},"jsdPublic":true},{"id":"3373016","author":{"accountId":"712020:b4c0c643-7648-43fd-ad84-b65f21a4e107","displayName":"Vismaya Thottada"},"body":"<p data-local-id="c210af563bc2">Hello <span data-local-id="8bf5e2ef-d83f-4c05-acbe-bb5d42025eff" data-type="mention" data-user-id="712020:036f5eba-7ec8-462c-b21b-264f8e744092">@Bikash Kumar</span> ,</p><p data-local-id="c3c28f2dd270">Client has has escalated this ticket. Could you please take a look into this. Thank you! </p>","created":"2026-09-30T13:04:53.775-0400","updated":"2026-09-30T13:05:01.528-0400","updateAuthor":{"accountId":"712020:b4c0c643-7648-43fd-ad84-b65f21a4e107","displayName":"Vismaya Thottada"},"jsdPublic":false},{"id":"3373325","author":{"accountId":"712020:20065f69-a041-443a-8b58-b79b1649d0b4","displayName":"Diego Buelvas"},"body":"<p data-local-id="98ea26ef96dd">Hello Erik Figueroa,</p><p data-local-id="f90a7e309fc4">I have taken ownership of this ticket and will be investigating it for you. Please allow some time for me to research the issue and I will get back with you just as soon as I have any information.</p><p data-local-id="b453ded9eeaf">Kind regards, </p>","created":"2026-09-30T16:53:07.363-0400","updated":"2026-09-30T16:53:07.363-0400","updateAuthor":{"accountId":"712020:20065f69-a041-443a-8b58-b79b1649d0b4","displayName":"Diego Buelvas"},"jsdPublic":true},{"id":"3373355","author":{"accountId":"712020:20065f69-a041-443a-8b58-b79b1649d0b4","displayName":"Diego Buelvas"},"body":"<p data-local-id="8b9796729221">Prepared: 30 September 2026  |  Analyst: Diego Buelvas  |  Status: <span data-local-id="9bf54a80-b2d0-461f-aa00-72e2322d1580" data-type="status" data-color="yellow">WORK IN PROGRESS</span></p><h2 data-local-id="535406d8f8bb">1. Ticket Details</h2><table data-local-id="0e3cb3a7-82de-4548-8010-14316372b197" data-width="760"><thead><tr><th data-local-id="ae2006468fbd" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="bd6653ddf908">Field</p></th><th data-local-id="6802a7070806" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="cff768eb48fd">Value</p></th></tr></thead><tbody><tr><td data-local-id="31463a8a2494" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="d39bf7e96cd0">Ticket</p></td><td data-local-id="c28a1a4c1dfe" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="a351ca351c05">RCS-29152</p></td></tr><tr><td data-local-id="e6497a8b44f4" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="6e6bf15a1f6c">Customer</p></td><td data-local-id="afcff2008274" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="d4a4297209d1">Starbucks Coffee Company (NA)</p></td></tr><tr><td data-local-id="45129bcae8b7" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="0f83ea553c3e">Issue Type</p></td><td data-local-id="044b6c2581e7" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="d141c8771c02">Incident</p></td></tr><tr><td data-local-id="0a09e0903d17" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="9499cf1ad73c">Priority</p></td><td data-local-id="c44356ff9b5d" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="80019988da5b">Medium</p></td></tr><tr><td data-local-id="f1a5372ed14d" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="96ce27ee219d">Status</p></td><td data-local-id="305c073b3a87" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="52ff1e69c596">Work in Progress</p></td></tr><tr><td data-local-id="5060d7e9589a" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="d9f65b0be948">Opened</p></td><td data-local-id="eabde5b4dcbd" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="4b8f08d1bfcf">28 September 2026</p></td></tr><tr><td data-local-id="57f22f6282f2" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="01bd1bed0ab0">Reporter</p></td><td data-local-id="72f995cd53d6" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="121032fa5cfb">Erik Figueroa (<a href="mailto:efiguero@starbucks.com">efiguero@starbucks.com</a>)</p></td></tr><tr><td data-local-id="cbd10a4af5ca" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="3f00951a6113">Assignee</p></td><td data-local-id="c474a64706cc" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="588202f02d39">Diego Buelvas (<a href="mailto:dbuelvas@apprissretail.com">dbuelvas@apprissretail.com</a>)</p></td></tr><tr><td data-local-id="dc9201fa8b9e" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="a0ceed85f147">Jira URL</p></td><td data-local-id="6c1e76e28efa" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="cbdde82f3b5a"><a href="https://trebuco.atlassian.net/browse/RCS-29152" data-card-appearance="inline">https://trebuco.atlassian.net/browse/RCS-29152</a> </p></td></tr></tbody></table><h2 data-local-id="edae0df853b7">2. Problem Statement</h2><p data-local-id="eb625fee4d09">&quot;The line items for cancels and line voids are not showing up on the receipt. The data is spotty — some show up and some do not.&quot; Two example receipts attached: a Cancel transaction (Store 48726, Reg 2, Trans #7651, 20 Sep 2026) showing negative amounts with blank item descriptions, versus a normal Sale transaction (Trans #5345) showing full item descriptions.</p><h2 data-local-id="fbe7cbb192e9">3. Client Profile</h2><table data-local-id="0dfd74f9-5959-4edd-97af-f8cc588b1463" data-width="760"><thead><tr><th data-local-id="cce5c6b4dbed" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="6fe27b353db2">Field</p></th><th data-local-id="c00bcc74aa91" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="ad7b0b21d398">Value</p></th></tr></thead><tbody><tr><td data-local-id="ffc20a2c5e69" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="7af3f159d988">Client ID</p></td><td data-local-id="60684fc19e28" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="6d16711e2c00">c166_sbx</p></td></tr><tr><td data-local-id="059971ca5bdc" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="e4fcdbed21fd">Region</p></td><td data-local-id="b51987dd726b" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="ba1af1fee10b">US</p></td></tr><tr><td data-local-id="8b49979d622f" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="bbfbef2454a0">ARDM Version</p></td><td data-local-id="4d30d5a6a232" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="a0dbd9e0cc18">V2 (snowtimeV2)</p></td></tr><tr><td data-local-id="52d085359d8c" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="0c70fd3a1b22">Snowflake</p></td><td data-local-id="6ae4e84aad12" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="dc840bd258f2">ARDM_PRODUCTION.C166_SBX (output) / C166_SBX_SNOWTIME (working)</p></td></tr><tr><td data-local-id="68060d0433bc" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="b5973d5ef81e">Status</p></td><td data-local-id="d1b3b1a32982" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="96fd9c617402">Live in production since 26 Aug 2026; full history backfilled from 23 Mar 2020</p></td></tr></tbody></table><h2 data-local-id="0166d041e4ea">4. Investigation</h2><h3 data-local-id="d00cdf714b1a">4.1 Reproduce the reported transaction</h3><p data-local-id="a79722c5533c">Query: located the exact transaction from the ticket screenshot (Store 48726, Ticket 7651, tradingday 2026-09-20) in ARDM_PRODUCTION.C166_SBX.</p><div data-local-id="e9a82ad8b405" data-type="panel-warning"><p data-local-id="f3694fdf11de">POINT OF FAILURE FOUND. All 3 line items have voidedflg=true and itemreceiptdescription=NULL — matches the blank receipt.</p></div><h3 data-local-id="fe14f1ab3380">4.2 Check reference data availability</h3><p data-local-id="ca257703489d">Query: looked up the 3 affected SKUs in REFERENCE_PRODUCT.</p><div data-local-id="cce25352424b" data-type="panel-warning"><p data-local-id="fac6b1e9134c">POINT OF FAILURE FOUND (data exists but unused). All 3 SKUs have valid names in the catalog (e.g. &quot;TR PINK DRINK&quot;, &quot;EXTRA ICE&quot;) — the correct value is available but never applied.</p></div><h3 data-local-id="3f82b8d94da5">4.3 Trace the mapping logic</h3><p data-local-id="3be1a49332fb">Query: read map_ardm_item.sql and enrich_ardm_item.sql.</p><div data-local-id="6ca0fa208a0c" data-type="panel-warning"><p data-local-id="0df38b83a4fe">POINT OF FAILURE FOUND. map_ardm_item.sql&#039;s CASE for itemreceiptdescription checks ref_receiptdescription IS NULL before name IS NULL; when both are NULL the result is raw NULL, not the intended &#039;NA&#039;. The enrichment fallback correctly replaces &#039;NA&#039;/&#039;None&#039;/&#039;Menu Item&#039; with the catalog name for voided items, but NULL IN (...) never evaluates true in SQL, so it never fires.</p></div><h3 data-local-id="5d9c85f5e6d3">4.4 Confirm parity with legacy pyardm</h3><p data-local-id="e8cfc422c7e6">Query: read pyardm ARDM_1_Item.sql.</p><div data-local-id="49135f45299b" data-type="panel-success"><p data-local-id="ae22e9548ff9">PASS (root cause classification). Same branch-order defect exists in legacy pyardm, with the same blind spot in its repair UPDATE. Inherited defect, not a SnowTime regression.</p></div><h3 data-local-id="70bcd45481e7">4.5 Measure scope</h3><p data-local-id="88735151fe97">Query: counted affected items by transactiontype (14 days, 2 months) and checked the client&#039;s full date range.</p><div data-local-id="e75e3763332a" data-type="panel-warning"><p data-local-id="d59aa9fb8e9e">POINT OF FAILURE FOUND. 14 days: 2,730,683 Sale/line-void items (1,961,699 txns) + 1,202,270 Cancel items (696,617 txns), plus smaller counts on Return/Exchange/PostVoid. 2 months: 12,841,455 affected items. Client history: 2020-03-23 to present — defect potentially reaches the full history.</p></div><h2 data-local-id="7a58067c682a">5. Root Cause Statement</h2><table data-local-id="9c546ef5-21ad-42e6-8573-9c252e0594fc" data-width="760"><tbody><tr><td data-local-id="a92976bfcc29" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="183a19533be7">What broke</p></td><td data-local-id="5089875df1aa" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="7f17bd9d3150">itemreceiptdescription on ardm_item is emitted as NULL instead of the &#039;NA&#039; placeholder for voided/cancelled lines with a missing source item name</p></td></tr><tr><td data-local-id="9e7fa4a5bd62" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="93b068e76736">Why</p></td><td data-local-id="36e886a4e441" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="0b361e7157e1">map_ardm_item.sql&#039;s CASE checks ref_receiptdescription before name, so a doubly-NULL case falls through to NULL; the enrichment fallback can never match a NULL value with IN (...). Same bug inherited from legacy pyardm.</p></td></tr><tr><td data-local-id="9306bf380b77" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="9690ccb32301">Scope</p></td><td data-local-id="3f7a914e812b" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="e91601c75aa5">c166_sbx, all voided/cancelled item lines (Sale line-void, Cancel, Return, Exchange, PostVoid); ~12.8M items in the last 2 months alone, potentially full history since 2020-03-23</p></td></tr><tr><td data-local-id="52063df416c0" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="970b46e55d62">Business impact</p></td><td data-local-id="1be1747f6a72" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="e45c5871fdbe">Receipts show blank item description instead of product name for any voided/cancelled line, even when the correct name exists in the catalog</p></td></tr><tr><td data-local-id="b464756df816" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="67eb2a74968a">Evidence</p></td><td data-local-id="822a79b8c67c" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="dbe676d35f0c">Reproduced exact ticket transaction (3 items, voidedflg=true, description=NULL); confirmed catalog has valid names for all 3 SKUs; confirmed scope via item counts</p></td></tr></tbody></table><h2 data-local-id="13f0e9bbe07a">7. Recommended Fix</h2><h3 data-local-id="f7659002ce5e">Option A — Patch the mapping CASE order (Recommended)</h3><p data-local-id="7663c3525c20">In dbt/clients/us/c166_sbx/models/mapping/map_ardm_item.sql (lines 158-163), move the name = &#039;None&#039; or name is null check to the first CASE branch:</p><pre data-local-id="666c9631c82f" data-wrap="true"><code>case
    when name = &#039;None&#039; or name is null                  then &#039;NA&#039;
    when ref_receiptdescription is null                 then SUBSTR(REPLACE(name, &#039;|&#039;, &#039;&#039;), 1, 58)
    when channeltype = &#039;Digital&#039;                        then SUBSTR(REPLACE(ref_receiptdescription, &#039;|&#039;, &#039;&#039;), 1, 58)
    else SUBSTR(REPLACE(name, &#039;|&#039;, &#039;&#039;), 1, 58)
end::VARCHAR as itemreceiptdescription</code></pre><p data-local-id="d90e898e7a4f">No change needed in enrich_ardm_item.sql — its fallback is already correct.</p><div data-local-id="927ab186258c" data-type="panel-info"><p data-local-id="aa278323fa73">History decision (pending): not forward-only — recommend REBUILD_RANGE repair over a recent window (e.g. last 90 days) rather than a full 6-year backfill.</p></div><h2 data-local-id="418748c5e518">8. Open Questions</h2><ol data-local-id="e68b571ca440"><li data-local-id="8ae93778b53f"><p data-local-id="1cce12e98417">Confirm which historical window actually needs repair.</p></li><li data-local-id="911f64d100f0"><p data-local-id="a2b2da7c6037">Apply the fix to map_ardm_item.sql — pending operator go-ahead (not yet applied).</p></li><li data-local-id="9b877bd0af44"><p data-local-id="ecf2b036d750">After fix + repair, verify the exact ticket transaction (Store 48726 / Ticket 7651) renders correctly.</p></li></ol><h2 data-local-id="c04112647ab4">9. Queries Run</h2><table data-local-id="6eeeb280-e046-43f5-af01-29c75b90d15b" data-width="760"><thead><tr><th data-local-id="7e14c6fa2fa4" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="40a50904a473">#</p></th><th data-local-id="ce58f5156d55" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="e4ce4b7d815c">Query</p></th><th data-local-id="4adf97eaf491" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="d7eb5db30607">Result</p></th></tr></thead><tbody></tbody></table><table data-local-id="486c83f6-233f-4d81-9e84-f41190cccdfb" data-width="760"><thead><tr><th data-local-id="56a43354c5f1" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="7f2165025113">#</p></th><th data-local-id="b192d996148b" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="e69f46fdc9f3">Query</p></th><th data-local-id="ead5e87442cd" data-background="#f0f1f2" style="background-color: #f0f1f2"><p data-local-id="ec3e042fd4c5">Result</p></th></tr></thead><tbody><tr><td data-local-id="226686f2ff8c" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="c869830b1375">1</p></td><td data-local-id="df5247c0aeef" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="6a654c43acf6">SELECT COUNT(*)... FROM ARDM_HEADER WHERE storeno=48726 AND ticketno=7651</p></td><td data-local-id="2c4f369a8cee" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="1ff085a0de55">1 row, tradingday 2026-09-20</p></td></tr><tr><td data-local-id="3f08daffeda5" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="d9854e1ba92e">2</p></td><td data-local-id="939b1ab9d133" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="79bf87313758">SELECT ... FROM ARDM_HEADER JOIN ARDM_ITEM WHERE storeno=48726 AND ticketno=7651</p></td><td data-local-id="9dfa90061a5c" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="9c402880ce3a">3 items, voidedflg=true, description=NULL</p></td></tr><tr><td data-local-id="3b6a98f49ad5" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="2d2d0dfb206a">3</p></td><td data-local-id="b31c6b2eac65" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="3c47a242cae1">SELECT ... FROM REFERENCE_PRODUCT WHERE articleid IN (3 SKUs)</p></td><td data-local-id="01c997c1c890" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="e4fd22c54003">All 3 SKUs have valid descriptions</p></td></tr><tr><td data-local-id="5be895db2c63" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="432a63b5d5e7">4</p></td><td data-local-id="52b527eb5a99" data-background="#ffffff" style="background-color: #ffffff"><p data-local-id="fd9ffc982247">SELECT ... GROUP BY transactiontype WHERE voidedflg=true AND description IS NULL, 14-day window</p></td>